// EMBER live voice session (POST /api/live): mints a short-lived, single-use Gemini Live token on the server so the
// API key never reaches the browser, and returns the session setup (model, voice, system prompt, the copilot's tools).
// The browser then talks to Gemini Live directly over a WebSocket: real-time speech in and speech out, with barge-in.
// SI disclosure: written with assistance from Claude (Anthropic). Speech generated by Google Gemini (SI).
import { TOOLS, SYSTEM } from './agent.js'

const LIVE = `
You are in a live spoken conversation. Talk like a person: short, natural sentences, no lists, no symbols, no markdown.
When the user asks to see, open, change, render or take apart something, call the tools first, then confirm in a few words.
If a tool takes a moment, you may say a few words while it runs. If you are interrupted, stop and listen.
You can render the ISS, the Moon base, the pressurized rover and every experiment apparatus in 3D in real time with explore_3d.`

export default async function handler(req, res) {
  const send = (code, obj) => { res.statusCode = code; res.setHeader('Content-Type', 'application/json'); res.setHeader('Cache-Control', 'no-store'); res.end(JSON.stringify(obj)) }
  if (req.method !== 'POST') return send(405, { error: 'POST only' })
  const key = process.env.GEMINI_API_KEY
  if (!key) return send(503, { error: 'Server is missing GEMINI_API_KEY.' })
  const model = process.env.GEMINI_LIVE_MODEL || 'gemini-3.8-live'
  const voice = process.env.GEMINI_LIVE_VOICE || 'Kore'
  const now = Date.now()
  try {
    const r = await fetch('https://generativelanguage.googleapis.com/v1beta/auth_tokens', {
      method: 'POST', headers: { 'x-goog-api-key': key, 'Content-Type': 'application/json' },
      body: JSON.stringify({ uses: 1, expireTime: new Date(now + 30 * 60e3).toISOString(), newSessionExpireTime: new Date(now + 2 * 60e3).toISOString() }),
    })
    const j = await r.json().catch(() => ({}))
    if (!r.ok || !j.name) return send(502, { error: 'Could not start a live voice session: ' + (j.error?.message || r.status) })
    send(200, {
      token: j.name, model,
      setup: {
        model: 'models/' + model,
        generationConfig: { responseModalities: ['AUDIO'], speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: voice } } } },
        systemInstruction: { parts: [{ text: SYSTEM('voice', '') + LIVE }] },
        tools: [{ functionDeclarations: TOOLS }],
        inputAudioTranscription: {},
        outputAudioTranscription: {},
      },
    })
  } catch (e) { send(502, { error: 'Could not reach Gemini: ' + String(e.message || e) }) }
}
